{"explanation":"The graphs of y = e^x and y = ln(x) are reflections of each other across y = x. Reflection swaps coordinates: every point (t, e^t) becomes (e^t, t), which lies on y = ln(x). This shows that the functions undo each other: ln(e^t) = t for every real t, and e^{ln(x)} = x for x > 0.","manimCode":"const heading = new Text({ text: 'Inverse functions: mirror across y = x', fontSize: 29, color: WHITE });
heading.moveTo([0, 3.35, 0]);
await scene.play(new Write(heading));

const ax = new Axes({ xRange: [-3, 3, 1], yRange: [-3, 3, 1], xLength: 5.6, yLength: 5.6, tips: false });
ax.moveTo([-1.7, -0.3, 0]);
const mirror = ax.plot(x => x, { color: GRAY, xRange: [-3, 3] });
const expCurve = ax.plot(x => Math.exp(x), { color: BLUE, xRange: [-3, Math.log(3)], numSamples: 250 });
const logCurve = ax.plot(x => Math.log(x), { color: ORANGE, xRange: [Math.exp(-3), 3], numSamples: 500 });
await scene.play(new Create(ax), new Create(mirror));
await scene.play(new Create(expCurve));

const expLabel = new MathTex({ latex: 'y=e^x', color: BLUE });
const logLabel = new MathTex({ latex: 'y=\\ln(x)', color: ORANGE });
const mirrorLabel = new MathTex({ latex: 'y=x', color: GRAY });
const pairLabel = new MathTex({ latex: '(t,e^t)\\;\\longleftrightarrow\\;(e^t,t)' });
const identityLabel = new MathTex({ latex: '\\ln(e^t)=t' });
for (const item of [expLabel, logLabel, mirrorLabel, pairLabel, identityLabel]) {
  await item.waitForRender();
}
expLabel.moveTo([3.45, 2.0, 0]);
logLabel.moveTo([3.45, 1.2, 0]);
mirrorLabel.moveTo([3.45, 0.4, 0]);
pairLabel.scale(0.72).moveTo([3.45, -0.75, 0]);
identityLabel.scale(0.9).moveTo([3.45, -1.65, 0]);
scene.add(expLabel, mirrorLabel);

const param = new ValueTracker(0.4);
const expPoint = new Dot({ point: ax.c2p(0.4, Math.exp(0.4)), color: BLUE });
const logPoint = new Dot({ point: ax.c2p(Math.exp(0.4), 0.4), color: ORANGE });
const bridge = new Polygon({ vertices: [expPoint.getCenter(), logPoint.getCenter()], color: YELLOW });
bridge.setFillOpacity(0);
bridge.setStrokeWidth(2);
scene.add(expPoint);
const travelingPoint = new Dot({ point: expPoint.getCenter(), color: YELLOW });
scene.add(travelingPoint);
await scene.play(new Transform(travelingPoint, new Dot({ point: logPoint.getCenter(), color: YELLOW })), new Create(logCurve));
scene.remove(travelingPoint);
scene.add(bridge, expPoint, logPoint, logLabel, pairLabel, identityLabel);

expPoint.addUpdater(mob => {
  const tVal = param.getValue();
  mob.moveTo(ax.c2p(tVal, Math.exp(tVal)));
});
logPoint.addUpdater(mob => {
  const tVal = param.getValue();
  mob.moveTo(ax.c2p(Math.exp(tVal), tVal));
});
bridge.addUpdater(mob => {
  const tVal = param.getValue();
  mob.setVertices([ax.c2p(tVal, Math.exp(tVal)), ax.c2p(Math.exp(tVal), tVal)]);
});
const hint = new Text({ text: 'Slide t to explore matching points', fontSize: 18, color: YELLOW });
hint.moveTo([3.45, -2.6, 0]);
scene.add(hint);
await scene.play(param.animateTo(-1.8));
await scene.play(param.animateTo(1));
await scene.play(param.animateTo(0.4));

const controls = new Controls(scene, { position: 'bottom-left', width: 260 });
controls.addSlider({ label: 't: input to exponential', min: -2.8, max: 1.02, value: 0.4, step: 0.01, onChange: val => { param.setValue(val); } });
makeHoverable(expPoint, scene, { hoverScale: 1.5 });
makeHoverable(logPoint, scene, { hoverScale: 1.5 });
